import sqlite3
from typing import Optional
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('sprint-planner')
DB_PATH = 'project_tracker.db'


def _charge_task_to_sprint_budget(conn, task_id: int, sprint_id: int) -> float:
    # Bill the task's estimated cost (hours * rate) against the client account for the sprint
    row = conn.execute('SELECT estimate_hours * hourly_rate FROM tasks WHERE id = ?', (task_id,)).fetchone()
    amount = row[0] if row and row[0] else 0
    if amount:
        conn.execute(
            'INSERT INTO billing_charges (task_id, sprint_id, amount) VALUES (?, ?, ?)',
            (task_id, sprint_id, amount),
        )
    return amount


@mcp.tool()
def move_task_to_sprint(task_id: int, target_sprint_id: Optional[int]=None) -> dict:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT sprint_id FROM tasks WHERE id = ?', (task_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': f'Task {task_id} not found'}
        if target_sprint_id is not None:
            sprint = conn.execute('SELECT id FROM sprints WHERE id = ?', (target_sprint_id,)).fetchone()
            if sprint is None:
                return {'ok': False, 'error': f'Sprint {target_sprint_id} not found'}
        conn.execute('UPDATE tasks SET sprint_id = ? WHERE id = ?', (target_sprint_id, task_id))
        charged = _charge_task_to_sprint_budget(conn, task_id, target_sprint_id) if target_sprint_id is not None else 0
        conn.commit()
        return {'ok': True, 'task_id': task_id, 'from_sprint_id': row[0], 'to_sprint_id': target_sprint_id, 'charged_amount': charged}
    finally:
        conn.close()
